import{_ as a,c as r,o as t,ae as n}from"./chunks/framework.tuuL-SzM.js";const i="/vulkan-renderer/depth-buffer.png",o="/vulkan-renderer/gpass-albedo.png",s="/vulkan-renderer/gpass-normal.png",l="/vulkan-renderer/gpass-metal-rougness.png",d="/vulkan-renderer/vulkan-final.png",h="/vulkan-renderer/tracy-frame.png",u="/vulkan-renderer/image.png",p="/vulkan-renderer/clion64_Oa9YtrakJS.gif",c="/vulkan-renderer/image-1.png",_=JSON.parse('{"title":"Vulkan deferred renderer","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"projects/vulkan-renderer.md","filePath":"projects/vulkan-renderer.md","lastUpdated":1758924781000}'),m={name:"projects/vulkan-renderer.md"};function g(f,e,b,w,k,y){return t(),r("div",null,e[0]||(e[0]=[n('<h1 id="vulkan-deferred-renderer" tabindex="-1">Vulkan deferred renderer <a class="header-anchor" href="#vulkan-deferred-renderer" aria-label="Permalink to &quot;Vulkan deferred renderer&quot;">​</a></h1><p><a href="https://github.com/GeleArthur/pretty-vulkan-printer" target="_blank" rel="noreferrer">GITHUB pretty vulkan printer</a></p><p>I created a vulkan renderer. It uses deferred rendering, bindless and tonemapping. Its named pretty vulkan printer (pvp).</p><p>A deferred renderer is special because instead of rendering the lit object directly (forward) we instead render in-between-images.</p><h2 id="deferred-rendering" tabindex="-1">Deferred rendering <a class="header-anchor" href="#deferred-rendering" aria-label="Permalink to &quot;Deferred rendering&quot;">​</a></h2><p>First, I do a depth pre pass. This way we can early out a texel before we start doing the heavy Geometry pass. <img src="'+i+'" alt="depth buffer"></p><p>The Geometry pass(Gpass) renders multiple images which we later combine into one final light pass.</p><h3 id="albedo" tabindex="-1"><strong>albedo</strong> <a class="header-anchor" href="#albedo" aria-label="Permalink to &quot;**albedo**&quot;">​</a></h3><p>This buffer shows the models with their textures applied on the mesh. <img src="'+o+'" alt="gpass-albedo"></p><h3 id="normal" tabindex="-1"><strong>normal</strong> <a class="header-anchor" href="#normal" aria-label="Permalink to &quot;**normal**&quot;">​</a></h3><p>This is the normal packed into 2 channels for extra detail. <img src="'+s+'" alt="gpass-normal"></p><h3 id="metal-and-rougness" tabindex="-1"><strong>metal and rougness</strong> <a class="header-anchor" href="#metal-and-rougness" aria-label="Permalink to &quot;**metal and rougness**&quot;">​</a></h3><ul><li>Red channel: How metallic an object is</li><li>Green channel: How rough an object is</li></ul><p><img src="'+l+'" alt="gpass-metal-rougness"></p><h3 id="final-render" tabindex="-1"><strong>final render</strong> <a class="header-anchor" href="#final-render" aria-label="Permalink to &quot;**final render**&quot;">​</a></h3><p>After the tone mapping we blit the final image onto the current swapchain. <img src="'+d+'" alt="final-render"></p><h1 id="extra-features" tabindex="-1">Extra features <a class="header-anchor" href="#extra-features" aria-label="Permalink to &quot;Extra features&quot;">​</a></h1><p>After I was done with the exams, I wanted to add some more things to my vulkan project.</p><ul><li>Move the window around without freezing</li><li>Tracy</li><li>Double buffering</li><li>Resize the window</li><li>Imgui</li></ul><h2 id="moving-the-window" tabindex="-1">Moving the window <a class="header-anchor" href="#moving-the-window" aria-label="Permalink to &quot;Moving the window&quot;">​</a></h2><p>I started with adding multi-threading. The main thread handle all the poll events from glfw. A separate thread is started for my render loop. One of the issues is that the render thread and main thread need to sync input calls. The main thread writes the input changes into a buffer and makes it thread-safe with a mutex. The render thread will lock the mutex when it wants to read the input. This change made me rethink a lot of my code base and a bunch of stuff had to be rewritten.</p><p>I learned why people don&#39;t like multithreading 😄.</p><h2 id="tracy" tabindex="-1">Tracy <a class="header-anchor" href="#tracy" aria-label="Permalink to &quot;Tracy&quot;">​</a></h2><p>Then I got distracted by the performance train and I started adding instrumental profiling code in my project and some of my suspicions got confirmed.</p><p>The timeline goes from left to right. The pink is the render thread and you can see that half of the frame I am WAITING!!!!. This is because I didn&#39;t have double buffering in my renderer so hopefully I can stop waiting once I have double buffering. <img src="'+h+'" alt="travy frame"></p><h2 id="double-buffering" tabindex="-1">Double buffering <a class="header-anchor" href="#double-buffering" aria-label="Permalink to &quot;Double buffering&quot;">​</a></h2><p>The problem with double buffering is that you need some things twice and some things once. In my old design all images where from the same class. Also the textures!!! With double buffering I need to duplicate the render images. The textures I don&#39;t need to duplicate. The camera buffer and light buffer also need to be duplicated.</p><p>Lights do not get updated every frame. But when they do, they need to be updated in the frame that&#39;s currently not active and in the future frame thats currently being rendered. My solution for this was a queue where every render buffer has their own queue and when its time to update the values it clears out the queue and updates all the values. When lights change both queues get the value. That way I can make sure both buffers get all the updates. This does mean I am doing double the work.</p><p><img src="'+u+'" alt="victory!"> Tracy shows that we are not waiting anymore!</p><h2 id="window-resizing" tabindex="-1">Window resizing <a class="header-anchor" href="#window-resizing" aria-label="Permalink to &quot;Window resizing&quot;">​</a></h2><p>Whenever you resize your window, I need to recreate all rendering images. Because all the images get recreated, all the views also need to be recreated. Which means that the descriptors need to be reassigned. This really feels like a chain of dependencies. I could have made a frame graph to get a graph of all the dependencies. But I went for an different solution. All the rendering images subscribe to the swapchain and the swapchain tells all images if there is a change. If there is a change, we recreate all images of all buffers. Also we wait with the change until the gpu is idle.</p><p><img src="'+p+'" alt="moving window"></p><h2 id="imgui" tabindex="-1">ImGUI <a class="header-anchor" href="#imgui" aria-label="Permalink to &quot;ImGUI&quot;">​</a></h2><p>You would think adding imgui would be easy? right? No, try it with multi threading. Because imgui doesn&#39;t expect multi threading, you have to make sure imgui doesn&#39;t call any of the glfw functions. So you have to handle the imgui input yourself. Luckily, imgui documentation is great and easy to read. 😃 There are functions in imgui so you can add input to the queue. But figuring this out and getting it to work was not easy 😛.</p><p><img src="'+c+'" alt="alt text"></p><h1 id="links" tabindex="-1">links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;links&quot;">​</a></h1><ul><li><a href="https://github.com/GeleArthur/pretty-vulkan-printer" target="_blank" rel="noreferrer">https://github.com/GeleArthur/pretty-vulkan-printer</a></li></ul>',37)]))}const I=a(m,[["render",g]]);export{_ as __pageData,I as default};
